 "content": "from collections import Counter


def transform(grid):
    """Fill between consecutive marker cells horizontally and vertically."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    height = len(grid)
    width = len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    marker = next((value for value, _ in counts.most_common() if value != background), None)
    result = [row[:] for row in grid]

    if marker is None:
        return result

    # Fill open intervals between adjacent markers in each row.
    for r in range(height):
        positions = [c for c in range(width) if grid[r][c] == marker]
        for left, right in zip(positions, positions[1:]):
            for c in range(left + 1, right):
                if grid[r][c] == background:
                    result[r][c] = 2

    # Fill open intervals between adjacent markers in each column.
    for c in range(width):
        positions = [r for r in range(height) if grid[r][c] == marker]
        for top, bottom in zip(positions, positions[1:]):
            for r in range(top + 1, bottom):
                if grid[r][c] == background:
                    result[r][c] = 2

    return result
